tryItForReal.commands:
-- release 1 (expand): add the new column, keep the old one
ALTER TABLE orders ADD COLUMN status_v2 text;
-- release 2: write both columns, backfill, then read the new one
UPDATE orders SET status_v2 = status WHERE status_v2 IS NULL;
-- release 3 (contract): only after nothing reads the old column
ALTER TABLE orders DROP COLUMN status;
